fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let gen: i32 = t / 30;
    host::display::clear(0x050510);
    let mut i: i32 = 0;
    while i < 40 {
        let mut hsh: i32 = i * 2654435761 + gen * 97;
        hsh = hsh * 1103515245 + 12345;
        let dx: i32 = ((hsh >> 16) & 32767) % cx;
        hsh = hsh * 1103515245 + 12345;
        let dy: i32 = ((hsh >> 16) & 32767) % cy;
        hsh = hsh * 1103515245 + 12345;
        let c: i32 = if ((hsh >> 16) & 1) == 1 { 0x66ccff } else { 0xff66aa };
        let s: i32 = 3 + ((hsh >> 20) & 3);
        host::display::fill_rect(cx - dx - s, cy - dy - s, s, s, c);
        host::display::fill_rect(cx + dx, cy - dy - s, s, s, c);
        host::display::fill_rect(cx - dx - s, cy + dy, s, s, c);
        host::display::fill_rect(cx + dx, cy + dy, s, s, c);
        i = i + 1;
    }
    host::display::draw_line(cx, 0, cx, h - 1, 0x1a1a30);
    host::display::draw_line(0, cy, w - 1, cy, 0x1a1a30);
    host::display::present();
}
